solution.js:
function countReachable(n, edges, start) {
  const next = Array.from({ length: n }, () => [])
  for (const [from, to] of edges) next[from].push(to)
  const seen = new Array(n).fill(false)
  seen[start] = true
  const stack = [start]
  let count = 1
  while (stack.length) {
    const node = stack.pop()
    for (const to of next[node]) {
      if (!seen[to]) {
        seen[to] = true
        count++
        stack.push(to)
      }
    }
  }
  return count
}

