def count_reachable(n, edges, start):
    nxt = [[] for _ in range(n)]
    for frm, to in edges:
        nxt[frm].append(to)
    seen = [False] * n
    seen[start] = True
    stack = [start]
    count = 1
    while stack:
        node = stack.pop()
        for to in nxt[node]:
            if not seen[to]:
                seen[to] = True
                count += 1
                stack.append(to)
    return count
